namespace Subscriptions;

public sealed class SubscriptionAccountService
{
    private readonly SubscriptionLifecycleService _lifecycle = new();
    private readonly SubscriptionBillingService _billing = new();
    private readonly SubscriptionEntitlementService _entitlements = new();
    private readonly SubscriptionNotificationService _notifications = new();

    public string Start(Account account, Plan plan, int seats, bool trialRequested) =>
        _lifecycle.Start(account, plan, seats, trialRequested);

    public string ChangePlan(Account account, Plan current, Plan next, int seats) =>
        _lifecycle.ChangePlan(account, current, next, seats);

    public string RecordInvoice(Account account, Plan plan, int seats, decimal credit) =>
        _billing.RecordInvoice(account, plan, seats, credit);

    public string ApplyPayment(Account account, PaymentAttempt payment) =>
        _billing.ApplyPayment(account, payment);

    public string GrantEntitlement(Account account, Entitlement entitlement) =>
        _entitlements.Grant(account, entitlement);

    public string RevokeEntitlement(Account account, Entitlement entitlement, bool force) =>
        _entitlements.Revoke(account, entitlement, force);

    public string QueueNotice(Account account, string kind, int daysUntilAction) =>
        _notifications.Queue(account, kind, daysUntilAction);

    public string ConfirmNotice(Account account, string kind, bool delivered) =>
        _notifications.Confirm(account, kind, delivered);
}

internal sealed class SubscriptionLifecycleService
{
    private readonly Dictionary<string, string> _subscriptions = new(StringComparer.Ordinal);

    public string Start(Account account, Plan plan, int seats, bool trialRequested)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!account.Verified) return "verification-required";
        if (account.InArrears) return "arrears-block";
        if (!plan.Countries.Contains(account.Country)) return "plan-unavailable";
        if (seats <= 0) return "invalid-seats";
        if (seats > plan.SeatLimit) return "seat-limit";
        if (trialRequested && !plan.TrialAvailable) return "trial-unavailable";
        _subscriptions[account.Id] = trialRequested ? "trial" : "active";
        return "started";
    }

    public string ChangePlan(Account account, Plan current, Plan next, int seats)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_subscriptions.TryGetValue(account.Id, out var status)) return "subscription-missing";
        if (status == "cancelled") return "subscription-cancelled";
        if (current.Code == next.Code) return "unchanged";
        if (!next.Countries.Contains(account.Country)) return "plan-unavailable";
        if (seats <= 0) return "invalid-seats";
        if (seats > next.SeatLimit) return "seat-limit";
        if (account.InArrears && next.MonthlyPrice > current.MonthlyPrice) return "upgrade-blocked";
        _subscriptions[account.Id] = "active:" + next.Code;
        return "plan-changed";
    }
}

internal sealed class SubscriptionBillingService
{
    private readonly Dictionary<string, decimal> _balances = new(StringComparer.Ordinal);

    public string RecordInvoice(Account account, Plan plan, int seats, decimal credit)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (string.IsNullOrWhiteSpace(plan.Code)) return "invalid-plan";
        if (seats <= 0) return "invalid-seats";
        if (seats > plan.SeatLimit) return "seat-limit";
        if (credit < 0m) return "invalid-credit";
        var gross = plan.MonthlyPrice * seats;
        if (credit > gross) return "credit-exceeds-charge";
        if (account.InArrears) gross += decimal.Round(gross * 0.05m, 2);
        var balance = decimal.Round(gross - credit, 2);
        _balances[account.Id] = balance;
        return balance == 0m ? "zero-invoice" : "invoice-recorded";
    }

    public string ApplyPayment(Account account, PaymentAttempt payment)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_balances.TryGetValue(account.Id, out var balance)) return "invoice-missing";
        if (string.IsNullOrWhiteSpace(payment.Reference)) return "payment-reference-required";
        if (payment.Amount <= 0m) return "invalid-payment";
        if (!payment.Accepted) return "payment-failed:" + payment.FailureCode;
        if (payment.Amount > balance) return "overpayment-review";
        balance -= payment.Amount;
        _balances[account.Id] = balance;
        if (balance > 0m) return "part-paid";
        if (account.InArrears) return "arrears-cleared";
        return "paid";
    }
}

internal sealed class SubscriptionEntitlementService
{
    private readonly Dictionary<string, HashSet<string>> _grants = new(StringComparer.Ordinal);

    public string Grant(Account account, Entitlement entitlement)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (string.IsNullOrWhiteSpace(entitlement.Code)) return "invalid-entitlement";
        if (entitlement.Quantity <= 0) return "invalid-quantity";
        if (account.InArrears) return "arrears-block";
        if (!account.Verified) return "verification-required";
        if (entitlement.Metered && entitlement.Quantity > 1000) return "metered-limit";
        if (!_grants.TryGetValue(account.Id, out var accountGrants))
            _grants[account.Id] = accountGrants = [];
        if (!accountGrants.Add(entitlement.Code)) return "already-granted";
        return "granted";
    }

    public string Revoke(Account account, Entitlement entitlement, bool force)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_grants.TryGetValue(account.Id, out var accountGrants)) return "account-has-no-grants";
        if (string.IsNullOrWhiteSpace(entitlement.Code)) return "invalid-entitlement";
        if (!accountGrants.Contains(entitlement.Code)) return "not-granted";
        if (entitlement.Metered && !force) return "force-required";
        if (entitlement.Quantity <= 0) return "invalid-quantity";
        if (force && !account.Verified) return "verification-required";
        accountGrants.Remove(entitlement.Code);
        return "revoked";
    }
}

internal sealed class SubscriptionNotificationService
{
    private readonly Dictionary<string, string> _notices = new(StringComparer.Ordinal);

    public string Queue(Account account, string kind, int daysUntilAction)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (string.IsNullOrWhiteSpace(account.Email)) return "email-required";
        if (!account.Email.Contains('@')) return "invalid-email";
        if (kind is not ("renewal" or "payment" or "cancellation")) return "invalid-kind";
        if (daysUntilAction < 0) return "invalid-day-count";
        if (kind == "renewal" && daysUntilAction > 30) return "too-early";
        if (kind == "payment" && !account.InArrears) return "payment-notice-not-needed";
        _notices[account.Id] = $"{kind}:{daysUntilAction}";
        return "queued";
    }

    public string Confirm(Account account, string kind, bool delivered)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_notices.TryGetValue(account.Id, out var notice)) return "notice-missing";
        if (string.IsNullOrWhiteSpace(kind)) return "kind-required";
        if (!notice.StartsWith(kind + ":", StringComparison.Ordinal)) return "kind-mismatch";
        if (!delivered) return "delivery-failed";
        if (!account.Verified) return "unverified-recipient";
        if (string.IsNullOrWhiteSpace(account.Email)) return "email-required";
        _notices.Remove(account.Id);
        return account.InArrears ? "confirmed-arrears" : "confirmed";
    }
}
